module clk_ratio_div_tb;

  logic       clk_i;
  logic       rst_ni;
  logic       en_i;
  logic       test_mode_en_i;
  logic [3:0] div_i;
  logic       div_valid_i;
  logic       div_ready_o;
  logic       clk_o;
  logic [3:0] cycl_count_o;

  clk_ratio_div dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .en_i(en_i),
    .test_mode_en_i(test_mode_en_i),
    .div_i(div_i),
    .div_valid_i(div_valid_i),
    .div_ready_o(div_ready_o),
    .clk_o(clk_o),
    .cycl_count_o(cycl_count_o)
  );

  initial begin clk_i = 1'b0; forever #5 clk_i = ~clk_i; end

  // Edge recorders: capture exact timestamps of clk_o transitions
  time rise_q[$];
  time fall_q[$];
  time ready_q[$];

  always @(posedge clk_o) rise_q.push_back($time);
  always @(negedge clk_o) fall_q.push_back($time);
  always @(posedge div_ready_o) ready_q.push_back($time);

  int fail_count = 0;

  task automatic fail(input string req, input string msg);
    fail_count++;
    $display("FAIL [%s]: %s", req, msg);
  endtask

  initial begin
    #4_000_000;
    $display("RESULT: FAIL (watchdog)");
    $finish;
  end

  task automatic drain_all();
    while (rise_q.size()  > 0) rise_q.pop_front();
    while (fall_q.size()  > 0) fall_q.pop_front();
    while (ready_q.size() > 0) ready_q.pop_front();
  endtask

  task automatic wait_rise(input int max_cycles, output bit ok, output time t);
    ok = 0; t = 0;
    for (int i = 0; i < max_cycles; i++) begin
      @(posedge clk_i);
      if (rise_q.size() > 0) begin
        t = rise_q.pop_front();
        ok = 1;
        return;
      end
    end
  endtask

  task automatic wait_fall(input int max_cycles, output bit ok, output time t);
    ok = 0; t = 0;
    for (int i = 0; i < max_cycles; i++) begin
      @(posedge clk_i);
      if (fall_q.size() > 0) begin
        t = fall_q.pop_front();
        ok = 1;
        return;
      end
    end
  endtask

  task automatic wait_ready(input int max_cycles, output bit ok, output time t);
    ok = 0; t = 0;
    for (int i = 0; i < max_cycles; i++) begin
      @(posedge clk_i);
      if (ready_q.size() > 0) begin
        t = ready_q.pop_front();
        ok = 1;
        return;
      end
    end
  endtask

  // Offer a new divisor; hold div_i stable until div_ready_o rises (H2).
  task automatic configure_div(input logic [3:0] d, output bit ok, output int wc);
    ok = 0; wc = 0;
    @(negedge clk_i);
    div_i = d;
    div_valid_i = 1;
    for (int i = 0; i < 100; i++) begin
      @(posedge clk_i);
      if (div_ready_o) begin ok = 1; break; end
      wc++;
    end
    @(negedge clk_i);
    div_valid_i = 0;
  endtask

  // Measure one period + high phase in raw time (P4 obligation).
  task automatic measure_period(input int max_cycles,
                                output bit ok,
                                output time period,
                                output time high);
    bit ok1, ok2, ok3;
    time t1, t2, t3;
    ok = 0;
    @(negedge clk_i);
    drain_all();
    wait_rise(max_cycles, ok1, t1);
    if (!ok1) return;
    wait_fall(max_cycles, ok2, t2);
    if (!ok2) return;
    wait_rise(max_cycles, ok3, t3);
    if (!ok3) return;
    period = t3 - t1;
    high   = t2 - t1;
    ok = 1;
  endtask

  initial begin
    rst_ni = 0;
    en_i = 1;
    test_mode_en_i = 0;
    div_i = 0;
    div_valid_i = 0;

    repeat (4) @(posedge clk_i);
    @(negedge clk_i);
    rst_ni = 1;
    repeat (4) @(posedge clk_i);

    // ===== R2: after reset, pass-through =====
    begin
      bit ok;
      time period, high;
      measure_period(100, ok, period, high);
      if (!ok) fail("R2", "No output after reset");
      else if (period != 10) fail("R2", $sformatf("After reset, period = %0t, expected 10", period));
    end

    // ===== P1/P2/P3/P4: period & duty for every divisor =====
    for (int d = 0; d <= 15; d++) begin
      bit ok;
      int wc;
      time period, high;
      logic [3:0] dv;
      dv = d[3:0];
      configure_div(dv, ok, wc);
      if (!ok) begin
        fail("P1", $sformatf("Could not configure divisor %0d", d));
        continue;
      end
      repeat (3) @(posedge clk_i);
      measure_period(200, ok, period, high);
      if (!ok) begin
        fail("P1", $sformatf("No output at divisor %0d", d));
        continue;
      end
      time expected_period = (d <= 1) ? 10 : d * 10;
      if (period != expected_period) begin
        fail("P1", $sformatf("Divisor %0d: period = %0t, expected %0t", d, period, expected_period));
      end
      if (d >= 2) begin
        time expected_high = d * 5;
        if (high != expected_high) begin
          fail("P2", $sformatf("Divisor %0d: high = %0t, expected %0t", d, high, expected_high));
        end
      end
    end

    // ===== H1: div_ready_o low while div_valid_i low =====
    begin
      bit h1_ok = 1;
      @(negedge clk_i);
      div_valid_i = 0;
      for (int i = 0; i < 20; i++) begin
        @(posedge clk_i);
        if (div_ready_o) h1_ok = 0;
      end
      if (!h1_ok) fail("H1", "div_ready_o high while div_valid_i low");
    end

    // ===== H3: same-value request granted immediately, no gating =====
    begin
      bit ok;
      int wc;
      time t1, t2, t3, t4;
      bit ok1, ok2, ok3, ok4;
      logic [3:0] d;
      d = 4'd4;
      configure_div(d, ok, wc);
      if (!ok) begin
        fail("H3", "Could not configure divisor 4");
      end else begin
        repeat (5) @(posedge clk_i);
        @(negedge clk_i);
        drain_all();
        wait_rise(100, ok1, t1);
        wait_rise(100, ok2, t2);
        if (!ok1 || !ok2) begin
          fail("H3", "No output before same-value request");
        end else begin
          @(negedge clk_i);
          div_i = d;
          div_valid_i = 1;
          ok = 0;
          for (int i = 0; i < 10; i++) begin
            @(posedge clk_i);
            if (div_ready_o) begin ok = 1; break; end
          end
