          div_valid_i = 0;
          if (!ok) begin
            fail("H3", "Same-value request not granted");
          end else begin
            wait_rise(100, ok3, t3);
            wait_rise(100, ok4, t4);
            if (!ok3 || !ok4) begin
              fail("H3", "No output after same-value request");
            end else if (t4 - t3 != 40) begin
              fail("H3", $sformatf("Gating during same-value request: period %0t, expected 40", t4 - t3));
            end
